// Self-check for the sidebar proxy in 10-meo-gateway.js.
//
// The sidebar's URLs are relative and the runtime resolves them, so a broken
// proxy fails only in a browser on another host — exactly the case that is easy
// to miss locally. Run: node test-sidebar-proxy.js
"use strict";

const assert = require("assert");
const http = require("http");
const express = require("express");
const bodyParser = require("body-parser");

// --- fake MEO service --------------------------------------------------------
const seen = [];
const service = http.createServer((req, res) => {
    seen.push({ method: req.method, url: req.url });
    if (req.url.startsWith("/api/v1/provision/events")) {
        res.writeHead(200, { "content-type": "text/event-stream" });
        res.write("event: provision.status\ndata: {\"state\":\"connecting\"}\n\n");
        setTimeout(() => res.write("event: provision.status\ndata: {\"state\":\"done\"}\n\n"), 50);
        return; // deliberately left open, like the real SSE feed
    }
    if (req.url === "/api/v1/devices/boom") {
        res.writeHead(404, { "content-type": "application/json" });
        res.end(JSON.stringify({ message: "no such device" }));
        return;
    }
    let body = "";
    req.on("data", (c) => { body += c; });
    req.on("end", () => {
        res.writeHead(200, { "content-type": "application/json" });
        res.end(JSON.stringify({ path: req.url, method: req.method, echo: body ? JSON.parse(body) : null }));
    });
});

// --- mount the real routes ---------------------------------------------------
// A fresh app per service URL: re-registering on one app would leave the first
// set of routes matching first, and the test would silently prove nothing.
function mount(serviceUrl) {
    const app = express();
    app.use(bodyParser.json());
    process.env.MEO_API_URL = serviceUrl;
    delete require.cache[require.resolve("./10-meo-gateway.js")];
    require("./10-meo-gateway.js")({
        httpAdmin: app,
        auth: { needsPermission: () => (req, res, next) => next() },
        nodes: { registerType() {}, createNode() {} }
    });
    return new Promise((resolve) => {
        const server = app.listen(0, () => resolve(server.address().port));
    });
}

function request(port, method, path, body) {
    return new Promise((resolve) => {
        const req = http.request({ port, method, path,
            headers: body ? { "content-type": "application/json" } : {} }, (res) => {
            let text = "";
            res.on("data", (c) => { text += c; });
            res.on("end", () => resolve({ status: res.statusCode, text, headers: res.headers }));
        });
        req.end(body ? JSON.stringify(body) : undefined);
    });
}

service.listen(0, async () => {
    try {
        const port = await mount("http://localhost:" + service.address().port);

        // GET is rewritten onto /api/v1/ and the query string survives.
        let r = await request(port, "GET", "/meo/api/devices?limit=2");
        assert.strictEqual(r.status, 200);
        assert.strictEqual(JSON.parse(r.text).path, "/api/v1/devices?limit=2");

        // A JSON body parsed by adminApp is re-serialized, not lost.
        r = await request(port, "PUT", "/meo/api/devices/abc", { name: "lamp" });
        assert.deepStrictEqual(JSON.parse(r.text).echo, { name: "lamp" });
        assert.strictEqual(JSON.parse(r.text).method, "PUT");

        // DELETE carries no body and must not invent one.
        r = await request(port, "DELETE", "/meo/api/devices/abc");
        assert.strictEqual(JSON.parse(r.text).echo, null);

        // The service's own status codes pass through unchanged (not 502).
        r = await request(port, "GET", "/meo/api/devices/boom");
        assert.strictEqual(r.status, 404);

        // SSE: events must arrive as they are written, not at stream end.
        const first = await new Promise((resolve, reject) => {
            const req = http.request({ port, path: "/meo/api/provision/events" }, (res) => {
                assert.strictEqual(res.headers["content-type"], "text/event-stream");
                res.once("data", (chunk) => { req.destroy(); resolve(String(chunk)); });
            });
            req.on("error", () => {});
            setTimeout(() => reject(new Error("no SSE data within 2s — it buffered")), 2000);
            req.end();
        });
        assert.ok(first.includes("provision.status"), "expected an SSE event, got: " + first);

        // An unreachable service is a 502, not a hang or a crash.
        const deadPort = await mount("http://127.0.0.1:1");
        r = await request(deadPort, "GET", "/meo/api/devices");
        assert.strictEqual(r.status, 502);

        console.log("sidebar proxy: all checks passed");
        process.exit(0);
    } catch (err) {
        console.error("FAILED:", err.message);
        process.exit(1);
    }
});
